package com.portfolio.controller;
import com.portfolio.model.Project; import com.portfolio.repository.ProjectRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/projects") public class ProjectController { private final ProjectRepository repo; public ProjectController(ProjectRepository r){repo=r;} @GetMapping public List<Project> all(){return repo.findAllByOrderByDisplayOrderAsc();} @GetMapping("/{id}") public ResponseEntity<Project> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public Project create(@RequestBody Project p){return repo.save(p);} @PutMapping("/{id}") public ResponseEntity<Project> update(@PathVariable Long id,@RequestBody Project p){return repo.findById(id).map(x->{x.setTitle(p.getTitle());x.setDescription(p.getDescription());x.setImage(p.getImage());x.setGithubUrl(p.getGithubUrl());x.setLiveUrl(p.getLiveUrl());x.setFeatured(p.isFeatured());x.setDisplayOrder(p.getDisplayOrder());x.setTechnologies(p.getTechnologies());return ResponseEntity.ok(repo.save(x));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }
